LIMITS=np.array([[-2.8973,2.8973],[-1.7628,1.7628],[-2.8973,2.8973],[-3.0718,-.0698],[-2.8973,2.8973],[-.0175,3.7525],[-2.8973,2.8973]])

def ik(pos, q0, rot=None):
    if rot is None: rot=np.diag([1.,-1.,-1.])
    def err(q):
        t=fk(q)
        return np.r_[(t[:3,3]-pos)*5,Rotation.from_matrix(rot@t[:3,:3].T).as_rotvec(),.005*(q-q0)]
    sol=least_squares(err,q0,bounds=(LIMITS[:,0]+.001,LIMITS[:,1]-.001),max_nfev=500,xtol=1e-12,ftol=1e-12,gtol=1e-12)
    t=fk(sol.x)
    if np.linalg.norm(t[:3,3]-pos)>.003: raise RuntimeError(f'IK failed: {t[:3,3]} vs {pos}')
    return sol.x

def send(r,actions,label):
    actions=np.array(actions)
    with (OUT/'actions.jsonl').open('a') as f:f.write(json.dumps({'label':label,'actions':actions.tolist()})+'\n')
    res=r.submit('joint_position',actions,dt=.1,cameras=None,video='none',include_depth=True,note=label)
    res.save(OUT/label)
    print(json.dumps(res.meta))
    return res

def move(pos,finger=.04,steps=35,label='move',rot=None):
    r=Robot();obs=r.get_obs(cameras=[],video='none');p=np.array(obs.meta['proprio']['now']);q0=p[:7];qt=ik(np.array(pos),q0,rot)
    print('target joints',qt,'FK',fk(qt)[:3,3])
    A=[np.r_[q0+(qt-q0)*u,finger,finger] for u in np.linspace(0,1,steps)]
    A.extend([np.r_[qt,finger,finger]]*10)
    return send(r,A,label)

def grip(finger,label='grip'):
    r=Robot();o=r.get_obs(cameras=[],video='none');p=np.array(o.meta['proprio']['now']);return send(r,[np.r_[p[23:30],finger,finger]]*15,label)

if __name__=='__main__':
    import argparse
    ap=argparse.ArgumentParser();ap.add_argument('--observe',action='store_true');ap.add_argument('--replay',action='store_true');ap.add_argument('--move',nargs=3,type=float);ap.add_argument('--finger',type=float,default=.04);ap.add_argument('--steps',type=int,default=35);ap.add_argument('--label',default='move');ap.add_argument('--grip',action='store_true');args=ap.parse_args()
    if args.observe: observe()
    elif args.move:move(args.move,args.finger,args.steps,args.label)
    elif args.grip:grip(args.finger,args.label)
    elif args.replay:
        r=Robot()
        for line in (OUT/'actions.jsonl').read_text().splitlines():
            entry=json.loads(line);res=r.submit('joint_position',entry['actions'],dt=.1,cameras=[],video='none',note=entry['label'])
            if res.done:break
